2	"use client";
3	
4	import { useState, useEffect, useRef, useCallback, useMemo, memo } from 'react';
5	import { createSupabaseBrowserClient } from '@/lib/supabase/client';
6	import { createTempRegistration } from '@/app/actions';
7	import Clock from '@/components/kiosk/Clock';
8	import { Bell, LogIn, LogOut, XCircle, UserPlus, Copy, Thermometer } from 'lucide-react';
9	import Image from 'next/image';
10	import { Button } from '@/components/ui/button';
11	import { useToast } from '@/hooks/use-toast';
12	
13	type KioskState = 'idle' | 'input' | 'success' | 'error' | 'register' | 'qr' | 'processing' | 'loading';
14	type AttendanceType = 'in' | 'out' | null;
15	
16	interface WbgtData {
17	  wbgt: number | null;
18	  timestamp: string | null;
19	}
20	
21	const AUTO_RESET_DELAY = 5000;
22	const PROCESSING_TIMEOUT = 15000;
23	
24	// --- Direct Supabase RPC call for attendance (bypasses Vercel serverless) ---
25	
26	async function recordAttendanceDirect(supabase: ReturnType<typeof createSupabaseBrowserClient>, cardId: string): Promise<{
27	  success: boolean;
28	  message: string;
29	  user: { display_name: string | null } | null;
30	  type: 'in' | 'out' | null;
31	}> {
32	  const normalizedCardId = cardId.replace(/:/g, '').toLowerCase();
33	
34	  const { data, error } = await supabase.schema('attendance').rpc('record_attendance_by_card', {
35	    p_card_id: normalizedCardId,
36	  });
37	
38	  if (error) {
39	    console.error('RPC error:', error);
40	    return { success: false, message: '打刻処理中にエラーが発生しました。', user: null, type: null };
41	  }
42	
43	  const result = data as {
44	    success: boolean;
45	    message: string;
46	    user: { display_name: string | null; discord_uid: string | null } | null;
47	    type: 'in' | 'out' | null;
48	  };
49	
50	  // display_nameがNULLの場合は「名無しさん」にフォールバック
51	  if (result.user && !result.user.display_name) {
52	    result.user.display_name = '名無しさん';
53	  }
54	
55	  return {
56	    success: result.success,
57	    message: result.message,
58	    user: result.user ? { display_name: result.user.display_name } : null,
59	    type: result.type,
60	  };
61	}
62	
63	// --- Helper function to isolate submission logic ---
64	
65	async function processSubmission(supabase: ReturnType<typeof createSupabaseBrowserClient>, submissionType: 'idle' | 'register', cardId: string) {
66	  if (submissionType === 'register') {
67	    return await createTempRegistration(cardId);
68	  }
69	  // 出退勤はSupabase RPCを直接呼ぶ（Vercelサーバーレスを経由しない）
70	  return await recordAttendanceDirect(supabase, cardId);
71	}
72	
73	// --- Memoized Components for Performance ---
74	
75	const WbgtDisplay = memo(({ wbgt }: { wbgt: number | null }) => {
76	  if (wbgt === null) {
77	    return (
78	        <div className="flex items-center gap-2 px-3 py-1 rounded-full text-sm bg-gray-500/20 text-gray-300">
79	            <span>WBGT: --.-°C</span>
80	        </div>
81	    );
82	  }
83	
84	  const getWbgtColor = (value: number) => {
85	    if (value >= 28) return 'bg-red-500/20 text-red-300'; // 厳重警戒以上
86	    if (value >= 25) return 'bg-orange-500/20 text-orange-300'; // 警戒
87	    if (value >= 21) return 'bg-yellow-500/20 text-yellow-300'; // 注意
88	    return 'bg-green-500/20 text-green-300'; // ほぼ安全
89	  };
90	
91	  const colorClass = getWbgtColor(wbgt);
92	
93	  return (
94	    <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-sm ${colorClass}`}>
95	      <Thermometer size={16} />
96	      <span>{`WBGT: ${wbgt.toFixed(1)}°C`}</span>
97	    </div>
98	  );
99	});
100	WbgtDisplay.displayName = 'WbgtDisplay';
101	
102	
