375	/**
376	 * 総活動時間を計算（特定ユーザー）
377	 */
378	export async function calculateTotalActivityTime(userId: string, days: number): Promise<number> {
379	  const supabase = await createSupabaseAdminClient();
380	  const startDate = format(subDays(new Date(), days), 'yyyy-MM-dd');
381	
382	  const { data: attendances } = await supabase
383	    .schema('attendance')
384	    .from('attendances')
385	    .select('*')
386	    .eq('user_id', userId)
387	    .gte('date', startDate)
388	    .order('timestamp', { ascending: true });
389	
390	  if (!attendances || attendances.length === 0) {
391	    return 0;
392	  }
393	
394	  let totalSeconds = 0;
395	  let lastInTime: Date | null = null;
396	
397	  for (const att of attendances) {
398	    if (att.type === 'in') {
399	      lastInTime = new Date(att.timestamp);
400	    } else if (att.type === 'out' && lastInTime) {
401	      const outTime = new Date(att.timestamp);
402	      totalSeconds += differenceInSeconds(outTime, lastInTime);
403	      lastInTime = null;
404	    }
405	  }
406	
407	  return totalSeconds;
408	}
409	
410	/**
411	 * 月次勤怠データを取得（カレンダー表示用）
412	 */
413	export async function getMonthlyAttendance(userId: string, month: Date) {
414	  const supabase = await createSupabaseServerClient();
415	  const start = startOfMonth(month);
416	  const end = endOfMonth(month);
417	
418	  const { data, error } = await supabase
419	    .schema('attendance')
420	    .from('attendances')
421	    .select('date, type')
422	    .eq('user_id', userId)
423	    .gte('date', format(start, 'yyyy-MM-dd'))
424	    .lte('date', format(end, 'yyyy-MM-dd'))
425	    .order('timestamp', { ascending: true });
426	
427	  if (error) {
428	    console.error('Error fetching monthly attendance:', error);
429	    return [];
430	  }
431	
432	  const dailyStatus: Record<string, 'in' | 'out' | 'mixed'> = {};
433	  
434	  (data || []).forEach(att => {
435	    if (!att.date) return;
436	    dailyStatus[att.date] = att.type as 'in' | 'out';
437	  });
438	
439	  return Object.keys(dailyStatus).map(date => ({
440	    date,
441	    status: dailyStatus[date]
442	  }));
443	}
